local function createStateMachine()
    local currentState: string? = "Idle"
    return {
        Idle = {
            Enter = function(self)
                print("Entering Idle")
            end,
            Execute = function(self)
                if game:GetService("RunService").Heartbeat then
                    currentState = "Running"
                end
            end,
            Exit = function(self)
                print("Exiting Idle")
            end,
        },
        Running = {
            Enter = function(self)
                print("Entering Running")
            end,
            Execute = function(self)
                if game:GetService("RunService").Heartbeat then
                    currentState = "Idle"
                end
            end,
            Exit = function(self)
                print("Exiting Running")
            end,
        },
    }
end
